-- 0184的原始行不稳定地省略sid；此补充迁移改用同一草稿行已保存的归一化身份键。
-- 每条更新限制5,000个快照主键，以避开TiDB单条大范围JSON Join的内存配额；
-- 每批都仅更新空负责人、仅单一负责人，且绑定同一工作空间、MCP批次哈希、店铺ID、ASIN与报告日期。
UPDATE ops_asin_daily_snapshots AS snapshot JOIN ops_external_sync_batches AS batch ON batch.workspaceId=snapshot.workspaceId AND batch.raw_response_hash=snapshot.source_batch_hash AND batch.source='lingxing_mcp' AND batch.data_domain='product_performance_daily' JOIN ops_external_sync_rows AS sync_row ON sync_row.workspaceId=batch.workspaceId AND sync_row.batch_id=batch.id AND JSON_UNQUOTE(JSON_EXTRACT(sync_row.normalized_data,'$.asin'))=snapshot.asin AND JSON_UNQUOTE(JSON_EXTRACT(sync_row.normalized_data,'$.storeId'))=snapshot.source_store_id AND JSON_UNQUOTE(JSON_EXTRACT(sync_row.normalized_data,'$.reportDate'))=snapshot.report_date SET snapshot.operator=JSON_UNQUOTE(JSON_EXTRACT(sync_row.source_data,'$.principal_names[0]')) WHERE snapshot.id BETWEEN 90001 AND 95000 AND snapshot.workspaceId=1 AND snapshot.source_type='lingxing_mcp' AND (snapshot.operator IS NULL OR TRIM(snapshot.operator)='') AND JSON_TYPE(JSON_EXTRACT(sync_row.source_data,'$.principal_names'))='ARRAY' AND JSON_LENGTH(JSON_EXTRACT(sync_row.source_data,'$.principal_names'))=1 AND TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(sync_row.source_data,'$.principal_names[0]')),''))<>'';
